        "AT", "AU", "BE", "CA", "CH", "DE", "DK", "ES", "FI", "FR", "GB", "GR",
        "HK", "IE", "IL", "IT", "JP", "KR", "LU", "NL", "NO", "NZ", "PL", "PT",
        "SE", "SG",
