#: Offshore holding domiciles, assigned to the United States. These are places a
#: company is registered, not places it operates or lists: the operating business is
#: usually American and the shares trade in New York, which is where FTSE's
#: country-of-risk method lands too.
OFFSHORE_HOLDCO = frozenset(
    {"BM", "BS", "GG", "GI", "IM", "JE", "KY", "MC", "MH", "PA", "VG"}
)

#: United States territories, which are the United States for a market split.
US_TERRITORY = frozenset({"PR"})

#: European Union and EEA members that FTSE classifies as frontier and the IMF calls
#: advanced. In the single market and trading in Europe, so developed ex-US here.
ADVANCED_FRONTIER = frozenset({"BG", "CY", "EE", "HR", "LT", "LV", "MT", "SI", "SK"})

#: Draw order, and the words the page prints for each. Never colour alone. Three, and
#: no fourth: "no market tier" is a question the page could not answer rather than an
#: answer, so what it cannot place is stated in prose instead of drawn.
TIERS: tuple[tuple[str, str], ...] = (
    ("US", "United States"),
    ("DM", "International Developed ex-US"),
    ("EM", "Emerging Markets"),
)

#: `data-tier` / `bar__seg--*` / `rowbar__fill--*` suffix per bucket.
TIER_CLASS = {"US": "us", "DM": "dm", "EM": "em"}


@dataclass(frozen=True)
class Band:
    """The coverage band: its stylesheet suffix, its words, and the metric gate."""

    key: str
    label: str
    chip: str
    show_metrics: bool


def coverage_band(coverage_pct: float) -> Band:
    """Coverage → the words and the gate. Boundaries are the contract's, not rounded."""
    if coverage_pct >= FULL_COVERAGE:
        return Band("full", f"{coverage_pct:.1f}% of weight covered", f"{coverage_pct:.1f}% covered", True)
    if coverage_pct >= PARTIAL_COVERAGE:
        return Band("partial", f"partial — {coverage_pct:.1f}% of weight", f"partial {coverage_pct:.1f}%", True)
    return Band("none", "not covered", f"{coverage_pct:.1f}% not covered", False)


def pct(weight_bp: int) -> str:
    """Basis points to a percentage, at the one precision basis points justify."""
    return f"{weight_bp / 100:.2f}%"


def number(value: float | None, places: int) -> str:
    return "not disclosed" if value is None else f"{value:.{places}f}"


def ratio(value: float | None, places: int, suffix: str = "") -> str:
    """A metric with its unit, or the honest absence of it."""
    return "not disclosed" if value is None else f"{value:.{places}f}{suffix}"


def days(count: int | None) -> str:
    if count is None:
        return "—"
    return f"{count:,} day" if count == 1 else f"{count:,} days"


MONTHS = ("Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec")


def long_date(value: str) -> str:
    """`2026-06-30` → `Jun 30, 2026`, built from the string, never through a date.

    The app's `formatDateLong` (`web/lib/format.ts`), for the same reason it gives:
    parsing an ISO date and formatting it back re-introduces a timezone, which is how
    a filing period becomes the day before for a reader west of UTC. A value this
    cannot read is returned unchanged — the page shows the data problem rather than
    hiding it behind a plausible-looking string.
    """
    match = re.match(r"^(\d{4})-(\d{2})-(\d{2})$", value or "")
    if not match:
        return value
    year, month, day = match.groups()
    index = int(month)
    if not 1 <= index <= 12:
        return value
    return f"{MONTHS[index - 1]} {int(day)}, {year}"


def _esc(text: str) -> str:
    return html.escape(text, quote=True)


def _plural(count: int, word: str, plural: str | None = None) -> str:
    return f"{count:,} {word if count == 1 else (plural or word + 's')}"


def _join(sentences: list[str]) -> str:
    """`a`, `a and b`, `a, b and c` — the way a sentence lists things."""
    if len(sentences) <= 1:
        return "".join(sentences)
    return f"{', '.join(sentences[:-1])} and {sentences[-1]}"


def _holdings(fund: dict) -> list[dict]:
    """Company-exposure rows by weight, then everything else, each in file order.

    The tie-breakers are explicit rather than "whatever order the file had": a page
    must be byte-identical for the same release, and two rows can share a weight and
    a name (two share classes of one company). Company id is the last key, so the
    order is a function of the data and not of the serializer.
    """
    rows = [row for row in fund.get("holdings", []) if row.get("weight_bp")]
    rows.sort(
        key=lambda row: (
            -row["weight_bp"],
            (row.get("name") or "").upper(),
            row.get("company_id") or "",
            row.get("ticker") or "",
        )
    )
    return rows


def load_contested(release_dir: Path) -> dict[str, str]:
    """`company_id → ISO country` for the companies the vote could not decide.

    A second, weaker answer published beside the decided one and never merged into it:
    the company tag keeps "we decline to place it", and the page places the company by
    the plurality so the holdings table and the market bar cannot disagree. Absent on a
    release published before 2026-11-05, which is not an error — the page then places
    only what the decided map covers, exactly as it did before.
    """
    path = release_dir / COUNTRIES_FILE
    if not path.exists():
        return {}
    try:
        document = json.loads(path.read_text())
    except (OSError, ValueError) as error:
        raise SystemExit(f"{path}: cannot read the country map ({error})") from error
    contested = document.get("contested") if isinstance(document, dict) else None
    if not isinstance(contested, dict):
        return {}
    return {
        company_id: code
        for company_id, code in contested.items()
        if isinstance(company_id, str)
        and isinstance(code, str)
        and len(code) == 2
        and code.isascii()
        and code.isupper()
    }


def load_countries(release_dir: Path) -> dict[str, str]:
    """`company_id → ISO country` from the release, or `{}` when it publishes none.

    A release that predates the country object is not an error: the page then says
    it cannot place the companies rather than colouring them by a guess. A country
    object that exists and cannot be read *is* an error — a broken artifact must
    fail the build, not quietly become "this release publishes no countries".
    """
    path = release_dir / COUNTRIES_FILE
    if not path.exists():
        return {}
    try:
        document = json.loads(path.read_text())
    except (OSError, ValueError) as error:
        raise SystemExit(f"{path}: cannot read the country map ({error})") from error
    companies = document.get("companies") if isinstance(document, dict) else None
    if not isinstance(companies, dict):
        raise SystemExit(f"{path}: no 'companies' object, so there is no country map")
    return {
        company_id: code
        for company_id, code in companies.items()
        if isinstance(company_id, str)
        and isinstance(code, str)
        and len(code) == 2
        and code.isascii()
        and code.isupper()
    }


def tier_of(country: str | None) -> str | None:
    """One domicile's bucket, or `None` when there is no domicile to classify.

    Total over every ISO alpha-2 code: a code FTSE does not classify is placed by one
    of the three rules above, so the bar never has a fourth segment to draw. `None` is
    reserved for "the release has no country for this company", which is a different
    statement and is answered by the release's contested map, not by a default here.
    """
    if not country:
        return None
    # The release's codes are ISO-3166 alpha-2 upper case and hash-checked, so this is
    # a no-op on valid data. It is here because the residue rule is total: without it a
    # lower-case "kr" would fall through to emerging and quietly put Korea in the wrong
    # bucket, which is the one failure mode a three-bucket table cannot show.
    code = country.strip().upper()
    if code == "US" or code in US_TERRITORY or code in OFFSHORE_HOLDCO:
        return "US"
    if code in DEVELOPED_EX_US or code in ADVANCED_FRONTIER:
        return "DM"
    return "EM"


@dataclass(frozen=True)
class Segment:
    """One drawn tier: its weight in the release, and the codes behind it."""

    key: str
    label: str
    weight_bp: int
    share: float
    codes: tuple[str, ...]


@dataclass(frozen=True)
class MarketSplit:
    """The bar, its denominator, and what the bar does not draw."""

    segments: tuple[Segment, ...]
    #: The bar's denominator: the weight the release can place in a market.
    placed_bp: int
    #: Weight the release cannot place, stated in prose rather than drawn.
    unplaced_bp: int
    #: Companies inside `unplaced_bp`.
    unplaced_companies: int


def market_split(
    rows: list[dict],
    countries: dict[str, str],
    contested: dict[str, str] | None = None,
) -> MarketSplit:
    """The bar: placed weight by market tier, in draw order, biggest included.

    Three segments and no fourth. A company is placed by the country the release
    decided, then by the release's *contested* answer for a company the vote could not
    decide. A position that resolved to no company is placed by the country its own
    filing states for it (`filed_country`), which is the only country evidence such a
    row has. Cash and derivative lines are never placed: they have no market.

    The denominator is the weight the release can place, not the whole fund. The
    coverage meter beside the bar prints the share that maps to a *company*, which is a
    different and narrower number, and the sentence under the bar says which total the
    bar is a share of. A tier with no weight is absent rather than drawn at zero — a
    zero-width segment is not a fact, and printing 0.00% three times makes a
    one-country fund look diversified.
    """
    contested = contested or {}
    totals = {key: 0 for key, _ in TIERS}
    codes: dict[str, set[str]] = {key: set() for key, _ in TIERS}
    unplaced_bp = 0
    unplaced_companies = 0
    for row in rows:
        weight_bp = int(row.get("weight_bp") or 0)
        if weight_bp <= 0:
            continue
        company_id = row.get("company_id")
        if company_id:
            country = countries.get(company_id) or contested.get(company_id)
        elif row.get("asset_cat") in ("cash", "derivative"):
            continue
        else:
            country = row.get("filed_country")
        key = tier_of(country)
        if key is None:
            unplaced_bp += weight_bp
            if company_id:
                unplaced_companies += 1
            continue
        totals[key] += weight_bp
        codes[key].add(country.strip().upper())
    placed = sum(totals.values())
    if placed <= 0:
        return MarketSplit((), 0, unplaced_bp, unplaced_companies)
    return MarketSplit(
        tuple(
            Segment(
                key,
                label,
                totals[key],
                totals[key] * 100.0 / placed,
                tuple(sorted(codes[key])),
            )
            for key, label in TIERS
            if totals[key] > 0
        ),
        placed,
        unplaced_bp,
        unplaced_companies,
    )


def fund_fragment(ticker: str) -> str | None:
    """`v3.<base64url>` with this fund at 100% — the app's own encoding, or `None`.

    `web/lib/fragment.ts` encodes a portfolio as `[mode, [[kind, key, amount], …]]`
    with the mode first and the racks sorted, base64url without padding. One fund at
    10,000 bp is a complete allocation, which is what the builder and the ledger
    require; anything else would be refused and land on the builder empty.
    """
    if not FRAGMENT_TICKER.match(ticker):
        return None
    payload = json.dumps(["bp", [["f", ticker, 10_000]]], separators=(",", ":"))
    encoded = base64.urlsafe_b64encode(payload.encode()).decode().rstrip("=")
    return f"v3.{encoded}"


def portfolio_link(ticker: str) -> str | None:
    """`/#v3…` — open this fund as a portfolio, in the builder that decodes it."""
    fragment = fund_fragment(ticker)
    return f"/#{fragment}" if fragment else None


def ledger_link(ticker: str) -> str | None:
    """`/x/#v3…` — the same allocation, opened in the look-through ledger."""
    fragment = fund_fragment(ticker)
    return f"/x/#{fragment}" if fragment else None


def compare_link(ticker: str) -> str | None:
    """`/compare/#v3…` — the same allocation, opening in comparison column A.

    `/compare` decodes a single-portfolio v3 fragment as side A and leaves side B
    empty (`web/lib/fragment.ts`, `decodeComparison`), so a fund page can hand the
    comparison one fund without inventing a second.
    """
    fragment = fund_fragment(ticker)
    return f"/compare/#{fragment}" if fragment else None


def _flag(country: str) -> str:
    """`US` → 🇺🇸, by the same regional-indicator arithmetic the app uses."""
    return "".join(chr(0x1F1E6 + ord(letter) - ord("A")) for letter in country)


def _sibling_links(funds: list[tuple[str, str]], *, exclude: str, limit: int) -> str:
    """Links to other fund pages: never this page, never twice, capped.

    A page that links to itself is a small lie the crawler and the sitemap both see,
    and a catalogue can list one ticker in two buckets, so the filter belongs here
    rather than at each call site. `limit` is applied after the filter, otherwise a
    list that starts with this fund would come up one link short.
    """
    seen = {exclude}
    links = []
    for ticker, name in funds:
        if ticker in seen:
            continue
        seen.add(ticker)
        links.append(
            f'<li><a href="/f/{_esc(ticker)}/">{_esc(name)}</a> '
            f'<span class="mono">{_esc(ticker)}</span></li>'
        )
        if len(links) == limit:
            break
    return "\n".join(links)


def render_page(
    fund: dict,
    *,
    issuer_funds: list[tuple[str, str]],
    indexable: bool = False,
    style: Style | None = None,
    similar: list[tuple[str, str]] | None = None,
    countries: dict[str, str] | None = None,
    contested: dict[str, str] | None = None,
) -> str:
    """One fund document → one standalone HTML page."""
    ticker = _esc(fund["ticker"])
    raw_name = fund["name"]
    name = _esc(raw_name)
    issuer = _esc(fund["issuer"])
    as_of = _esc(fund["as_of"])
    filed_at = _esc(fund["filed_at"])
    as_of_long = _esc(long_date(fund["as_of"]))
    filed_at_long = _esc(long_date(fund["filed_at"]))
    lag = fund.get("lag_days")
    source_url = _esc(fund.get("source_url") or "")
    coverage = float(fund.get("coverage_pct") or 0.0)
    band = coverage_band(coverage)
    metrics = fund.get("metrics") or {}
    rows = _holdings(fund)
    total_rows = len(rows)
    mapped = sum(1 for row in rows if row.get("company_id"))
    shown = rows[:TOP_HOLDINGS]
    split = market_split(rows, countries or {}, contested)
    segments = split.segments
    # Only the positive classification is printed. The release's `etf` flag is a name
    # test, and a fund whose name does not say "ETF" can still be one (VTI is filed as
    # "Vanguard Total Stock Market Index Fund"), so "not an ETF" is not a fact this
    # page can assert — and a wrong wrapper label is worse than no label.
    wrapper = "ETF" if fund.get("etf") else ""

    # The answer. The brief's sentence when every position is a named company —
    # `VTI holds 1,269 companies; the largest is Apple at 6.12% of the fund` — and
    # its honest form when the release could not map some of them. Then the market
    # split, then the limits in the same breath, because a number without its
    # coverage and its as_of is the thing this page exists not to print.
    if not rows:
        answer = (
            f'<p class="answer__sentence">{ticker} filed no positions for this period in this '
            "release.</p>"
        )
    elif not mapped:
        answer = (
            f'<p class="answer__sentence">{ticker} files '
            f'<strong>{_plural(total_rows, "position")}</strong>, and none of them maps to a '
            "company we can name.</p>"
        )
    else:
        largest = next((row for row in rows if row.get("company_id")), None) or rows[0]
        largest_name = _esc(largest.get("name") or "unknown")
        largest_weight = pct(largest.get("weight_bp") or 0)
        largest_phrase = "the largest is" if largest.get("company_id") else "the largest position is"
        if mapped == total_rows:
            lead = f"{ticker} holds <strong>{_plural(total_rows, 'company', 'companies')}</strong>"
        else:
            lead = (
                f"{ticker} files <strong>{_plural(total_rows, 'position')}</strong>, "
                f"<strong>{_plural(mapped, 'company', 'companies')}</strong> of them companies we "
                f"can name"
            )
        answer = (
            f'<p class="answer__sentence">{lead}; {largest_phrase} <strong>{largest_name}</strong> '
            f"at <strong>{largest_weight}</strong> of the fund.</p>"
        )

    if segments:
        # `61.2% is in US companies, 27.4% in other developed markets, 9.1% in
        # emerging markets, and 2.3% is in companies whose domicile this release
        # does not publish` — the design system's split sentence.
        parts = []
        for index, segment in enumerate(segments):
            value = f"<strong>{segment.share:.2f}%</strong>"
            if segment.key == "US":
                phrase = "in US companies"
            elif segment.key == "DM":
                phrase = "in other developed markets"
            elif segment.key == "EM":
                phrase = "in emerging markets"
            elif segment.key == "OTHER":
                phrase = "in domiciles in neither list"
            else:
                phrase = "is in companies whose domicile this release does not publish"
            if index == 0 and not phrase.startswith("is "):
                phrase = f"is {phrase}"
            parts.append(f"{value} {phrase}")
        answer += (
            f'\n        <p class="answer__sentence">Of the {coverage:.1f}% of the fund we can map '
            f"to a company, {_join(parts)}.</p>"
        )

    note_parts = [
        f"Coverage <strong>{coverage:.1f}%</strong>",
        f"reporting period <strong>{as_of_long}</strong>",
        f"filed <strong>{filed_at_long}</strong>",
    ]
    if lag is not None:
        note_parts.append(f"{days(lag)} later")
    answer_note = '<p class="answer__note">' + " · ".join(note_parts) + ".</p>"

    # The holdings table. The row's left edge is the market tier and the two-letter
    # code beside the company prints the same fact in text; the caption says so,
    # because a colour a reader cannot see must not be the only carrier.
    holdings_rows = []
    for rank, row in enumerate(shown, start=1):
        company = _esc(row.get("name") or "unknown")
        company_id = row.get("company_id")
        if company_id:
            country = (countries or {}).get(company_id) or (contested or {}).get(company_id) or ""
        elif row.get("asset_cat") in ("cash", "derivative"):
            country = ""
        else:
            country = row.get("filed_country") or ""
        # The row contract is the ledger's (`web/components/LedgerTable.tsx`): the tier
        # is an attribute the stylesheet turns into the row's left edge, the two-letter
        # code prints the same fact in text, and a company whose country this release
        # does not publish carries `data-country-missing` rather than a guessed tier.
        attributes = ""
        if country:
            attributes = f' data-country="{_esc(country)}" data-tier="{_esc(tier_of(country))}"'
        elif company_id:
            attributes = ' data-country-missing="true"'
        company_cell = f'<a href="/c/#{_esc(company_id)}">{company}</a>' if company_id else company
        symbol = _esc(row.get("ticker") or "")
        if symbol:
            company_cell += f' <span class="mono tiny muted">{symbol}</span>'
        chips = ""
        if not company_id:
            chips += ' <span class="chip">unmapped</span>'
        category = _esc(row.get("asset_cat") or "")
        if category and category != "equity":
            # A non-equity row can outrank real companies by weight (a
            # securities-lending money-market position is often third), so the type
            # is printed beside the name rather than in a column a phone hides.
            chips += f' <span class="chip">{category}</span>'
        if country:
            country_cell = (
                f'<span class="country-tag"><span aria-hidden="true">{_flag(country)}</span> '
                f"{_esc(country)}</span>"
            )
        elif company_id:
            country_cell = '<span class="muted">Unknown</span>'
        else:
            country_cell = '<span class="muted">—</span>'
        holdings_rows.append(
            f"<tr{attributes}>"
            f'<td class="num">{rank}</td>'
            f"<td>{company_cell}{chips}</td>"
            f"<td>{country_cell}</td>"
            f'<td class="num">{pct(row.get("weight_bp") or 0)}</td>'
            "</tr>"
        )
    holdings_html = "\n            ".join(holdings_rows)

    if total_rows > len(shown):
        holdings_note = (
            f"The {len(shown)} largest of {_plural(total_rows, 'position')}, by the weight the "
            "fund filed. A weight is this company's share of the fund, not of any portfolio."
        )
    else:
        holdings_note = (
            f"Every one of the {_plural(total_rows, 'position')} this fund filed, by weight. "
            "A weight is this company's share of the fund, not of any portfolio."
        )
    if countries:
        tier_caption = (
            " The row's left edge is the company's market tier, and the two-letter code beside it "
            "prints the same fact: blue United States, ochre international developed ex-US, deeper "
            "ochre emerging. Every domicile has one of the three — an offshore holding domicile "
            "such as Bermuda or the Cayman Islands is the United States, because that is where its "
            "shares trade. A company the vote could not decide is placed by the release's "
            "plurality answer, and a position that resolved to no company by the country its own "
            f"filing states. Domiciles follow the {TIER_CONVENTION}, as of {TIER_AS_OF}."
        )
    else:
        tier_caption = ""

    # The concentration figures, or the notice that says why they are withheld. The
    # gate is coverage first: a figure computed from the mapped part of a fund we can
    # only partly see describes our mapping, so it is the band that decides. A release
    # that publishes no metrics is the second case, and it says so rather than showing
    # three "not disclosed" cards under a heading that promises numbers.
    if band.show_metrics and metrics:
        concentration_html = f"""<div class="doc-grid">
          <div class="card">
            <p class="eyebrow">Concentration</p>
            <p class="subtitle doc-value">{ratio(metrics.get("hhi"), 4)}</p>
          </div>
          <div class="card">
            <p class="eyebrow">Same-size companies</p>
            <p class="subtitle doc-value">{ratio(metrics.get("effective_n"), 1)}</p>
          </div>
          <div class="card">
            <p class="eyebrow">Biggest 10 companies</p>
            <p class="subtitle doc-value">{ratio(metrics.get("top10_pct"), 2, "%")}</p>
          </div>
        </div>
        <p class="muted small doc-note">Concentration is the sum of squared weights — 0 means
        spread evenly, 1 means all in one company. Same-size companies is how many equal-sized
        companies would be spread the same way. Biggest 10 companies is the share of the fund
        held by its ten largest. All three are computed from the {coverage:.1f}% of the fund's
        weight that maps to a company; the rest is cash, derivatives, and positions outside our
        mapping.</p>"""
    elif band.show_metrics:
        concentration_html = f"""<div class="notice notice--quiet">
          <p><strong>No concentration figures in this release.</strong> Coverage is
          {coverage:.1f}%, which is inside the band that shows them, but this release publishes
          none for {ticker} — so none are computed here.</p>
        </div>"""
    else:
        concentration_html = f"""<div class="notice">
          <p><strong>Concentration figures are withheld.</strong> Only {coverage:.1f}% of this
          fund's weight maps to a company we can identify, and below 60% a concentration number
          computed from the mapped part would describe our mapping rather than the fund. The gap
          is ours, not the fund's: every position here is filed by the fund and counted in the
          coverage meter below.</p>
        </div>"""

    # The market bar, its legend, and the table that prints the same numbers. The
    # denominator is the mapped weight, never the whole fund: the coverage meter beside
    # it prints that share, and this is its composition, so the two cannot disagree
    # about what "mapped" means. Nothing is drawn when the release published no
    # domiciles — a made-up tier is worse than an empty chart.
    if not countries:
        market_intro = ""
        market_html = """<div class="notice">
          <p><strong>Not traced.</strong> This release does not publish a domicile for each
          company, so the market split is not shown rather than guessed. The holdings and
          coverage figures above are unaffected.</p>
        </div>"""
    elif not segments:
        market_intro = ""
        market_html = """<div class="notice notice--quiet">
          <p>None of this fund's weight can be placed in a market, so there is no market split to
          draw.</p>
        </div>"""
    else:
        market_intro = (
            "Share of the weight this fund's filing places in a market, by tier. Developed and "
            f"emerging follow the {TIER_CONVENTION}, as of {TIER_AS_OF}; an offshore holding "
            "domicile such as Bermuda or the Cayman Islands is the United States, because that is "
            "where its shares trade. Cash and derivatives are outside the bar."
        )
        bars = "\n              ".join(
            f'<span class="bar__seg bar__seg--{TIER_CLASS[segment.key]}" '
            f'style="width:{segment.share:.4f}%"></span>'
            for segment in segments
        )
        legend = "\n              ".join(
            f'<span class="legend__item"><span class="legend__swatch bar__seg--'
            f'{TIER_CLASS[segment.key]}" aria-hidden="true"></span>{_esc(segment.label)} '
            f'<span class="mono">{segment.share:.2f}%</span></span>'
            for segment in segments
        )
        table_rows = "\n                ".join(
            "<tr>"
            f"<td>{_esc(segment.label)}</td>"
            f'<td class="mono">{_esc(", ".join(segment.codes)) or "—"}</td>'
            f'<td class="num">{segment.share:.2f}%</td>'
            "</tr>"
            for segment in segments
        )
        spoken = ", ".join(f"{segment.label} {segment.share:.2f}%" for segment in segments)
        remainder = ""
        if split.unplaced_bp > 0:
            remainder = (
                f" A further {pct(split.unplaced_bp)} of the fund is weight the release cannot "
                f"place in a market — {_plural(split.unplaced_companies, 'company', 'companies')} "
                "with no country answer, and positions whose filing states none — and it is not "
                "drawn."
            )
        market_html = f"""<div class="bar bar--tall" role="img" aria-label="Share of the placed weight: {spoken}">
              {bars}
            </div>
            <div class="legend">
              {legend}
            </div>
            <div class="table-wrap">
              <table class="table">
                <caption class="small muted">The bar above, as numbers: each tier's share of the
                placed weight, and the two-letter domicile codes behind it. Each share is rounded
                once, from the fund's exact weights, so the column can sit 0.01 from 100%.{remainder}</caption>
                <thead>
                  <tr><th scope="col">Market tier</th><th scope="col">Codes</th>
                  <th scope="col" class="num">Share</th></tr>
                </thead>
                <tbody>
                  {table_rows}
                </tbody>
              </table>
            </div>"""

    uncovered = max(0.0, 100.0 - coverage)
    if band.key == "full":
        band_sentence = (
            "At least 70% of this fund's weight maps to a company we can name, which is the band "
            "where a concentration figure describes the fund rather than our mapping."
        )
    elif band.key == "partial":
        band_sentence = (
            "Between 60% and 70% of this fund's weight maps to a company we can name, so the "
            "concentration figures above are a floor on what the fund holds rather than its exact "
            "shape."
        )
    else:
        band_sentence = (
            "Below 60% of this fund's weight maps to a company we can name, so the concentration "
            "figures are withheld rather than shown small."
        )
    coverage_html = f"""<div class="meter" aria-hidden="true">
          <span class="meter__track"><span class="meter__fill"
            style="width:{min(coverage, 100.0):.1f}%"></span></span>
          <span class="meter__label small muted">Weight mapped to a company — {coverage:.1f}%</span>
        </div>
        <p class="row"><span class="chip chip--{band.key}">{band.chip}</span>
        <span class="muted small">of this fund's weight maps to a company we can name</span></p>
        <p class="muted small doc-note">{band_sentence} The other {uncovered:.1f}% is cash,
        derivatives, and positions our mapping cannot identify. It is counted, not hidden.</p>"""

    # The actions the brief asks for, plus the ledger and the directory. Each one is
    # an anchor with a finished `href` computed here, so the page works with
    # JavaScript off; `data-fragment` is what `SCRIPT` at the foot of the document
    # hooks, and a page whose ticker the app's grammar refuses gets no fragment link
    # at all rather than a link that would land on an empty builder.
    portfolio = portfolio_link(fund["ticker"])
    compare = compare_link(fund["ticker"])
    ledger = ledger_link(fund["ticker"])
    if portfolio and compare:
        actions = (
            f'<a class="btn btn--primary" data-fragment href="{_esc(portfolio)}">'
            "Add this fund to a portfolio</a>\n"
            f'          <a class="btn" data-fragment href="{_esc(compare)}">Compare</a>\n'
            + (
                f'          <a class="btn" data-fragment href="{_esc(ledger)}">'
                "See it in your portfolio</a>\n"
                if ledger
                else ""
            )
            + '          <a class="btn btn--quiet" href="/funds/">Browse all funds</a>'
        )
    else:
        actions = '<a class="btn btn--primary" href="/funds/">Browse all funds</a>'
    script = SCRIPT if portfolio else ""

    panels = ""
    here = fund["ticker"]
    issuer_links = _sibling_links(issuer_funds, exclude=here, limit=SAME_ISSUER_LINKS)
    similar_links = _sibling_links(similar or [], exclude=here, limit=SIMILAR_FUND_LINKS)
    if issuer_links or similar_links:
        panel_parts = []
        if issuer_links:
            panel_parts.append(
                f"""<section class="panel">
            <div class="panel__head"><h2 class="panel__title">More from {issuer}</h2></div>
            <div class="panel__body"><ul class="doc-links">
              {issuer_links}
            </ul></div>
          </section>"""
            )
        if similar_links:
            # The heading states the grouping, because it is a claim about the funds in
            # it; the note says how the grouping was made and what it is not.
            heading = f"Similar {_esc(style.label)} funds" if style is not None else "Similar funds"
            panel_parts.append(
                f"""<section class="panel">
            <div class="panel__head"><h2 class="panel__title">{heading}</h2></div>
            <div class="panel__body">
              <p class="muted small doc-note">The same style bucket, most-covered first. A
              bucket, not a recommendation.</p>
              <ul class="doc-links">
              {similar_links}
              </ul>
            </div>
          </section>"""
            )
        panels = f'<div class="doc-grid">\n          {chr(10).join(panel_parts)}\n        </div>'

    np_port = (
        f'<a href="{source_url}" rel="nofollow noopener">Form N-PORT on SEC EDGAR</a>'
        if source_url
        else "Form N-PORT on SEC EDGAR"
    )
    robots = "" if indexable else '<meta name="robots" content="noindex, follow">\n'

    return f"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>{ticker} holdings — what {name} owns</title>
<meta name="description" content="{_esc(f"{fund['ticker']} ({raw_name}): {_plural(mapped, 'company', 'companies')}, {coverage:.1f}% of the fund's weight mapped. Holdings as of {fund['as_of']}, filed {fund['filed_at']}, from the fund's own SEC Form N-PORT.")}">
<link rel="canonical" href="{SITE}/f/{ticker}/">
{robots}<link rel="stylesheet" href="/{CSS_NAME}">
</head>
<body>
<a class="skip-link" href="#main">Skip to content</a>
<header class="site-header">
  <div class="shell site-header__inner">
    <a class="wordmark" href="/">UnpackFund</a>
    <nav class="site-nav" aria-label="Sections">
      <a href="/">Portfolio</a>
      <a href="/compare/">Compare</a>
      <a href="/c/">Companies</a>
      <a href="/funds/" aria-current="page">Funds</a>
      <a href="/methodology/">How it works</a>
    </nav>
    <div class="header-tools"><a class="search-trigger" href="/funds/">Find a fund</a></div>
  </div>
</header>
<main id="main" class="shell page">
  <div class="stack stack--loose">

    <div class="stack stack--tight">
      <p class="eyebrow">Fund</p>
      <h1 class="title">{name}</h1>
      <div class="row">
        <span class="chip chip--mono">{ticker}</span>
        {f'<span class="chip">{wrapper}</span>' if wrapper else ""}
        <span class="chip">{issuer}</span>
      </div>
      <p class="lede">What this fund owns, according to its own quarterly filing with the SEC —
      every position it filed, at the weight it filed.</p>
    </div>

    <section aria-labelledby="answer-heading">
      <h2 id="answer-heading" class="visually-hidden">The short answer</h2>
      <div class="answer">
        {answer}
        {answer_note}
      </div>
    </section>

    <section aria-labelledby="holdings-heading" class="stack stack--tight">
      <h2 id="holdings-heading" class="title--sm">Largest holdings</h2>
      <p class="muted small doc-note">{holdings_note}</p>
      <div class="table-wrap">
        <table class="table">
          <caption class="small muted">Holdings of {name}, as of {as_of}, by the weight the fund
          filed. Weights are the fund's own and are not rescaled, so they may not add to exactly
          100%.{tier_caption}</caption>
          <thead>
            <tr><th scope="col" class="num">#</th><th scope="col">Company</th>
            <th scope="col">Country</th><th scope="col" class="num">Weight</th></tr>
          </thead>
          <tbody>
            {holdings_html}
          </tbody>
        </table>
      </div>
    </section>

    <section aria-labelledby="concentration-heading" class="stack stack--tight">
      <h2 id="concentration-heading" class="title--sm">Concentration</h2>
      {concentration_html}
    </section>

    <section aria-labelledby="market-heading" class="stack stack--tight">
      <h2 id="market-heading" class="title--sm">Where these companies are</h2>
      {f'<p class="muted small doc-note">{market_intro}</p>' + chr(10) + "      " if market_intro else ""}{market_html}
    </section>

    <section aria-labelledby="coverage-heading" class="stack stack--tight">
      <h2 id="coverage-heading" class="title--sm">How much of the fund we can see</h2>
      {coverage_html}
    </section>

    <section aria-labelledby="provenance-heading" class="stack stack--tight">
      <h2 id="provenance-heading" class="title--sm">Where these numbers come from</h2>
      <div class="doc-grid">
        <div class="card">
          <p class="eyebrow">Period end</p>
          <p class="subtitle doc-value">{as_of}</p>
          <p class="muted tiny">the date these holdings describe</p>
        </div>
        <div class="card">
          <p class="eyebrow">Filed with the SEC</p>
          <p class="subtitle doc-value">{filed_at}</p>
          <p class="muted tiny">when EDGAR received the filing</p>
        </div>
        <div class="card">
          <p class="eyebrow">Filing lag</p>
          <p class="subtitle doc-value">{days(lag)}</p>
          <p class="muted tiny">period end to filing date</p>
        </div>
      </div>
      <p class="muted small doc-note">The filing is the fund's own: {np_port}. Holdings change
      after the period end, so a position listed here may already be gone, and a position the
      fund bought since is not listed at all.</p>
    </section>

    <section aria-labelledby="actions-heading" class="stack stack--tight">
      <h2 id="actions-heading" class="title--sm">Look through this fund</h2>
      <p class="muted small doc-note">Open it as a 100% portfolio: every company the fund holds,
      at the fund's own weights, next to anything else you own. The calculation runs in your
      browser and nothing is saved.</p>
      <div class="row">
          {actions}
      </div>
    </section>

    {panels}

  </div>
</main>
<footer class="site-footer">
  <div class="shell site-footer__inner">
    <p class="notice-line"><strong>Not investment advice.</strong> UnpackFund shows what funds
    hold, from public SEC filings. It is not a recommendation to buy, hold or sell anything, and
    the operator is not a registered investment adviser.
    <a href="/disclaimer/">Read the full disclaimer</a>.</p>
    <p class="notice-line">Holdings come from quarterly filings and typically describe a
    portfolio <strong>60 to 150 days</strong> old; they can be wrong. Verify anything that
    matters against this fund's own documents.</p>
    <p class="notice-line">Source: SEC EDGAR (Form N-PORT). No SEC seal or logo is used, and the
    SEC has not reviewed or endorsed this site. UnpackFund is not affiliated with any fund
    issuer.</p>
    <nav class="footer-links" aria-label="About this site">
      <a href="/methodology/">Methodology</a>
      <a href="/about/">About</a>
      <a href="/glossary/">Glossary</a>
      <a href="/disclaimer/">Disclaimer</a>
      <a href="/privacy/">Privacy</a>
      <a href="/terms/">Terms</a>
    </nav>
  </div>
</footer>
{script}
</body>
</html>
"""


def _style_index(catalogue: dict[str, list]) -> dict[str, list[tuple[str, str]]]:
    """Style bucket key → funds in it, most useful first.

    Built once for the whole release: 8,983 classifications of names, then a lookup
    per page. A fund whose name supports no bucket is simply absent, and its page
    falls back to the issuer list.
    """
    ranked: dict[str, list[tuple[tuple, str, str]]] = {}
    for ticker, row in catalogue.items():
        if not SAFE_TICKER.match(ticker):
            continue
        name, issuer = row[0], row[1] if len(row) > 1 else ""
        style = resolve(name, issuer)
        if style is None:
            continue
        coverage = float(row[3]) if len(row) > 3 and row[3] is not None else 0.0
        # Alphabetical would show the same A-names forever and hide half the bucket.
        # A visitor wants a peer they can act on, so: ETFs first (the wrapper most
        # readers are looking for, read off the name like everything else here), then
        # the funds we can see the most of, then ticker for determinism. A bucket of
        # 552 therefore shows its best twelve on every page rather than a rotating
        # window: repetition across pages is the lesser cost, and the reader of one
        # page cannot see it.
        key = (0 if "ETF" in name.upper() else 1, -coverage, ticker)
        ranked.setdefault(style.key, []).append((key, ticker, name))
    index: dict[str, list[tuple[str, str]]] = {}
    for style_key, items in ranked.items():
        items.sort()
        index[style_key] = [(ticker, name) for _, ticker, name in items]
    return index


def _issuer_index(catalogue: dict[str, list]) -> dict[str, list[tuple[str, str]]]:
    by_issuer: dict[str, list[tuple[str, str]]] = {}
    for ticker, row in catalogue.items():
        if not SAFE_TICKER.match(ticker):
            continue
        by_issuer.setdefault(row[1], []).append((ticker, row[0]))
    for funds in by_issuer.values():
        funds.sort(key=lambda item: item[0])
    return by_issuer


def _manifest_hashes(release_dir: Path) -> dict[str, str]:
    """`sha256` per fund ticker from the release manifest; empty when unusable.

    The manifest lists every generated file as `{path, bytes, sha256}`, so the
    hashes of 8,983 documents arrive in one 1.4 MB read instead of 300 MB of file
    hashing — and the value is the one the validator already re-checks, so this
    cannot quietly disagree with a release that passed. Whatever the manifest does
    not cover is hashed from disk by `_fund_hashes`.
    """
    try:
        manifest = json.loads((release_dir / "manifest.json").read_text())
    except (OSError, ValueError):
        return {}
    entries = manifest.get("files") if isinstance(manifest, dict) else None
    if not isinstance(entries, list):
        return {}
    prefix, suffix = "funds/", ".json"
    hashes: dict[str, str] = {}
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        path, digest = entry.get("path"), entry.get("sha256")
        if not isinstance(path, str) or not isinstance(digest, str):
            continue
        if path.startswith(prefix) and path.endswith(suffix) and "/" not in path[len(prefix) :]:
            hashes[path[len(prefix) : -len(suffix)]] = digest
    return hashes


def _fund_hashes(release_dir: Path) -> dict[str, str]:
    """`sha256` per fund document in a release directory.

    The manifest is the source; a document it does not name is hashed from disk,
    so a release written without a manifest still diffs correctly and a manifest
    that is short of a file cannot silently hide a change.
    """
    hashes = _manifest_hashes(release_dir)
    funds_dir = release_dir / FUNDS_DIR
    if not funds_dir.is_dir():
        return hashes
    on_disk = {path.stem for path in funds_dir.glob("*.json")}
    for ticker in sorted(on_disk - set(hashes)):
        hashes[ticker] = sha256_hex((release_dir / FUNDS_FILE.format(ticker=ticker)).read_bytes())
    return hashes


def changed_tickers(release_dir: Path, parent_dir: Path) -> set[str]:
    """Tickers whose fund document differs from the parent release, new ones included.

    A fund is rebuilt when it is new, when its document bytes differ, or when the
    parent has no document for it. A fund that left the catalogue is not returned:
    this decides what to write, never what to delete.
    """
    release = _fund_hashes(release_dir)
    parent = _fund_hashes(parent_dir)
    return {
        ticker
        for ticker, digest in release.items()
        if SAFE_TICKER.match(ticker) and parent.get(ticker) != digest
    }


def read_only_file(path: Path) -> set[str]:
    """Tickers from a newline-separated file; `#` starts a comment anywhere on a line.

    Upper-cased on the way in because tickers are upper-case everywhere else in
    the release; a hand-written list should not need to know that.
    """
    tickers: set[str] = set()
    for line in path.read_text().splitlines():
        ticker = line.split("#", 1)[0].strip()
        if ticker:
            tickers.add(ticker.upper())
    return tickers


def _looks_like_release(path: Path) -> bool:
    """A directory this can diff against: fund hashes or the documents themselves."""
    return (path / "manifest.json").is_file() or (path / FUNDS_DIR).is_dir()


def sitemap_xml(tickers: list[str]) -> str:
    """Every published page, as a sitemap.

    8,983 fund pages plus the app's own routes is far below the 50,000-URL and
    50 MB limits, so this is one file, not an index. `lastmod` is deliberately
    omitted: the pages carry their own dates, and a `lastmod` that means "the
    build ran" would tell a crawler nothing true.
    """
    urls = [f"{SITE_ORIGIN}{route}" for route in APP_ROUTES]
    urls += [f"{SITE_ORIGIN}/f/{ticker}/" for ticker in tickers]
    body = "".join(f"  <url><loc>{html.escape(url)}</loc></url>\n" for url in urls)
    return (
        '<?xml version="1.0" encoding="UTF-8"?>\n'
        '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'
        f"{body}"
        "</urlset>\n"
    )


def robots_txt() -> str:
    """Allow everything and point at the sitemap.

    There is nothing here to hide: every page is meant to be read. The file
    exists because a site with no `robots.txt` is served one by the host, and
    that one carries no `Sitemap:` line.
    """
    return (
        "# UnpackFund: every page is meant to be read.\n"
        "User-agent: *\n"
        "Allow: /\n"
        f"\nSitemap: {SITE_ORIGIN}/sitemap.xml\n"
    )


def build(
    release_dir: Path,
    out_dir: Path,
    *,
    only: set[str] | None = None,
    limit: int | None = None,
    indexable: bool = False,
) -> dict:
    """Write fund pages under `out_dir`, plus the shared stylesheet.

    With `only`, write those tickers and nothing else. Every other file already
    in `out_dir` is left exactly as it was: this runs against the live `web/out`,
    so a partial rebuild that swept the directory would take the site's fund
    directory down with it. A ticker in `only` that this release does not publish
    is reported back, not raised — a stale name in a list must not fail a deploy.
    """
    catalogue_doc = json.loads((release_dir / CATALOGUE_FILE).read_text())
    catalogue: dict[str, list] = catalogue_doc["funds"]
    by_issuer = _issuer_index(catalogue)
    by_style = _style_index(catalogue)
    countries = load_countries(release_dir)
    contested = load_contested(release_dir)

    out_dir.mkdir(parents=True, exist_ok=True)
    (out_dir / CSS_NAME).write_text(stylesheet(), encoding="utf-8")

    catalogue_tickers = [ticker for ticker in catalogue if SAFE_TICKER.match(ticker)]
    tickers = catalogue_tickers
    requested: int | None = None
    unmatched: list[str] = []
    if only is not None:
        wanted = {ticker.upper() for ticker in only}
        requested = len(wanted)
        unmatched = sorted(wanted - set(catalogue_tickers))
        tickers = [ticker for ticker in catalogue_tickers if ticker in wanted]
    if limit is not None:
        tickers = tickers[:limit]

    written = 0
    skipped: list[str] = []
    bytes_total = 0
    bands = {"full": 0, "partial": 0, "not-covered": 0}
    for ticker in tickers:
        fund_path = release_dir / FUNDS_FILE.format(ticker=ticker)
        if not fund_path.exists():
            skipped.append(ticker)
            continue
        fund = json.loads(fund_path.read_text())
        others = [
            (other, other_name)
            for other, other_name in by_issuer.get(fund["issuer"], [])
            if other != ticker
        ]
        style = resolve(fund["name"], fund.get("issuer") or "")
        page = render_page(
            fund,
            issuer_funds=others,
            indexable=indexable,
            style=style,
            similar=(
                [pair for pair in by_style.get(style.key, []) if pair[0] != ticker]
                if style is not None
                else []
            ),
            countries=countries,
            contested=contested,
        )
        target = out_dir / "f" / ticker / "index.html"
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(page, encoding="utf-8")
        written += 1
        bytes_total += len(page.encode())
        coverage = float(fund.get("coverage_pct") or 0.0)
        if coverage >= FULL_COVERAGE:
            bands["full"] += 1
        elif coverage >= PARTIAL_COVERAGE:
            bands["partial"] += 1
        else:
            bands["not-covered"] += 1

    # One flag flips the package: page-level `noindex`, the sitemap, and robots.
    # A site that is `noindex` but advertises a sitemap tells a crawler two
    # different things, so these three move together or not at all.
    sitemap_written = robots_written = False
    if indexable:
        (out_dir / "sitemap.xml").write_text(sitemap_xml(tickers), encoding="utf-8")
        (out_dir / "robots.txt").write_text(robots_txt(), encoding="utf-8")
        sitemap_written = robots_written = True

    return {
        "pages": written,
        "sitemap": sitemap_written,
        "robots": robots_written,
        "skipped": skipped,
        "bytes": bytes_total,
        "median_bytes": bytes_total // written if written else 0,
        "bands": bands,
        "catalogue": len(catalogue),
        # How many company → domicile decisions the release published. Zero means the
        # market section will say it cannot place the companies, not that none exist.
        "countries": len(countries),
        # `requested` is None for a full rebuild, which is how a caller tells the
        # two modes apart without repeating the flag it passed in.
        "requested": requested,
        "unmatched": unmatched,
        # Catalogue entries this run did not rewrite; on a full rebuild it is 0,
        # and on a partial one it is the number of pages left as they were.
        "untouched": len(catalogue_tickers) - written - len(skipped),
    }


#: The page's one script. Eleven lines, inline, no `eval`, no `innerHTML`, no
#: storage, no request — and nothing depends on it: each action is an anchor whose
#: `href` was computed by `portfolio_link`/`compare_link`/`ledger_link` above, so a
#: visitor with JavaScript off still lands on the builder, the comparison and the
#: ledger with the fund already allocated. The handler exists so a plain left click
#: is one code path, and it leaves a modified click, a middle click, and keyboard
#: activation to the browser.
SCRIPT = """<script>
(function () {
  var links = document.querySelectorAll("a[data-fragment]");
  for (var i = 0; i < links.length; i++) {
    links[i].addEventListener("click", function (event) {
      if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
      event.preventDefault();
      window.location.assign(this.getAttribute("href"));
    });
  }
})();
</script>"""

#: The page stylesheet *is* the app's design system: `web/app/globals.css`, copied
#: byte for byte at build time, plus the rules a static document needs and the app
#: does not. Copying rather than restating is the point — a token, a primitive or a
#: dark-scheme value that moves in the app moves here on the next build, and the
#: page cannot drift into a second palette. `stylesheet()` is what proves it: it
#: fails the build when that file is missing rather than shipping an unstyled page.
CSS_RULES = """

/* ------------------------------------------------------------------------- */
/* Document rules — a static fund page. Nothing here restates a token.       */
/* ------------------------------------------------------------------------- */

/* Three-up facts. The app lays these out with its own components; a document
 * gets a grid, so a phone drops to one column without a media query. */
.doc-grid {
  display: grid;
  gap: var(--space-3);
  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));
}

/* A figure that is compared rather than read: same digits, same width. */
.doc-value {
  font-variant-numeric: tabular-nums;
}

/* A note beside a chart or under a table keeps the measure of the page rather
 * than the width of the viewport. */
.doc-note {
  max-width: var(--measure);
}

/* Sibling funds: a list of names, not a paragraph. */
.doc-links {
  display: flex;
  flex-direction: column;
  gap: var(--space-2);
  list-style: none;
  font-size: var(--text-14);
}

.doc-links .mono {
  color: var(--graphite);
}
"""


def stylesheet(globals_css: Path | None = None) -> str:
    """The app's stylesheet, verbatim, then the document rules.

    Fails rather than degrades: a page whose stylesheet is missing is not a page,
    and a release directory is the wrong thing to point a silent fallback at. The
    provenance line says where the bytes came from, so a served page can be traced
    to one build.
    """
    path = globals_css or REPO_ROOT / "web" / "app" / "globals.css"
    if not path.exists():
        raise SystemExit(f"{path}: the design system is missing, so there is no page to style")
    header = (
        "/* Generated by pipeline.fund_pages — web/app/globals.css copied verbatim.\n"
        " * Do not edit: the app's stylesheet is the only source of these tokens. */\n"
    )
    return f"{header}{path.read_text(encoding='utf-8')}{CSS_RULES}"


def newest_release(root: Path | None = None) -> Path:
    """The release to generate from when none is named: newest with a catalogue.

    Release directories are named `YYYY-MM-DD.N`, so lexicographic order is
    chronological; a partially-built directory has no catalogue and is skipped.
    """
    if root is None:
        root = REPO_ROOT / "artifacts" / "universe-c" / "releases"
    candidates = [
        path for path in root.iterdir() if (path / CATALOGUE_FILE).exists()
    ] if root.exists() else []
    if not candidates:
        raise SystemExit(f"no release with a catalogue under {root}")
    return max(candidates, key=lambda path: path.name)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Write one plain HTML page per fund.")
    parser.add_argument("--release", type=Path, default=None)
    parser.add_argument("--out", required=True, type=Path)
    selection = parser.add_mutually_exclusive_group()
    selection.add_argument(
        "--only-file",
        type=Path,
        default=None,
        help="rebuild only the tickers listed in this file (one per line, '#' comments)",
    )
    selection.add_argument(
        "--changed-from",
        type=Path,
        default=None,
        help="rebuild only the funds whose document differs from this release",
    )
    parser.add_argument("--limit", type=int, default=None)
    parser.add_argument("--indexable", action="store_true")
    args = parser.parse_args(argv)

    # The parent says what changed; it cannot say what to build. Without
    # `--release` the newest release would be picked, which is a different
    # question from the one the flag asks.
    if args.changed_from is not None and args.release is None:
        print(
            "--changed-from needs --release: the parent says what changed, not what to build",
            file=sys.stderr,
        )
        return 2
    if args.changed_from is not None and not _looks_like_release(args.changed_from):
        print(f"not a release directory: {args.changed_from}", file=sys.stderr)
        return 2

    release = args.release or newest_release()
    print(f"release: {release}")

    only: set[str] | None = None
    if args.only_file is not None:
        try:
            only = read_only_file(args.only_file)
        except OSError as error:
            print(f"cannot read --only-file: {error}", file=sys.stderr)
            return 2
        print(f"only: {len(only):,} ticker(s) from {args.only_file}")
    elif args.changed_from is not None:
        only = changed_tickers(release, args.changed_from)
        print(f"changed since {args.changed_from.name}: {len(only):,} fund(s)")

    stats = build(
        release, args.out, only=only, limit=args.limit, indexable=args.indexable
    )
    if stats["requested"] is not None:
        print(
            f"partial rebuild: {stats['pages']:,} page(s) written, "
            f"{stats['untouched']:,} left untouched"
            + (
                f", {len(stats['unmatched']):,} requested ticker(s) not in the catalogue: "
                f"{', '.join(stats['unmatched'][:5])}"
                if stats["unmatched"]
                else ""
            )
        )
    if stats["pages"] == 0:
        # A full rebuild that wrote nothing means the release path is wrong, which
        # is why it is one line and a failure. A partial rebuild that wrote
        # nothing means no fund changed since the parent — the normal quiet day —
        # so the same warning is printed and the run still succeeds.
        print("no pages written — is the release directory correct?", file=sys.stderr)
        if only is None:
            return 1
        print(
            "nothing to rebuild: no requested or changed fund in this release",
            file=sys.stderr,
        )
        return 0
    print(
        f"{stats['pages']:,} fund page(s) of {stats['catalogue']:,} in the catalogue, "
        f"{stats['bytes'] / 1e6:.1f} MB ({stats['median_bytes'] / 1e3:.1f} kB median) — "
        f"coverage bands: {stats['bands']['full']:,} full, "
        f"{stats['bands']['partial']:,} partial, "
        f"{stats['bands']['not-covered']:,} not covered"
    )
    if stats["countries"]:
        print(f"country map: {stats['countries']:,} companies placed by the release")
    else:
        print(
            "country map: none in this release — the market section will say so",
            file=sys.stderr,
        )
    if stats["skipped"]:
        print(
            f"skipped {len(stats['skipped'])} ticker(s) with no fund document: "
            f"{', '.join(stats['skipped'][:5])}",
            file=sys.stderr,
        )
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
